#!/usr/bin/env ruby
require'json';require'fileutils';root=File.expand_path('..',__dir__);assets=File.expand_path('../Client/assets',root);rows=[]
Dir.glob(File.join(assets,'**/Spine/**/skeleton.json.meta')).sort.each do|sm|am=sm.sub('/Spine/','/Atlas/').sub('/skeleton.json.meta','/skeleton.atlas.meta');atlas=am.sub(/\.meta$/,'');texture=File.join(File.dirname(atlas),File.readlines(atlas,chomp:true).find{|l|l.match?(/\.(?:png|jpg|jpeg|webp)\r?$/i)}.to_s.delete_suffix("\r"));s=JSON.parse(File.read(sm));a=File.file?(am) ? JSON.parse(File.read(am)) : {};rows<<{skeleton:sm.delete_prefix(assets+'/'),atlas:atlas.delete_prefix(assets+'/'),atlasExists:File.file?(atlas),textureExists:File.file?(texture),configuredAtlasUuid:s.dig('userData','atlasUuid'),actualAtlasUuid:a['uuid'],linked:s.dig('userData','atlasUuid')==a['uuid']};end;checks={pairsPresent:!rows.empty?,allAtlasPresent:rows.all?{|r|r[:atlasExists]},allTexturesPresent:rows.all?{|r|r[:textureExists]},allUuidLinksCorrect:rows.all?{|r|r[:linked]}};report={schemaVersion:1,pairs:rows.length,checks:checks,rows:rows,creatorImporterConsoleEvidence:false};out=File.join(root,'docs/generated/creal11-spine-atlas.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");abort("CREAL11 failed: #{checks}")unless checks.values.all?;puts "CREAL11 PASS: #{rows.length} Spine atlas links repaired; editor console deferred"
